@gene("s2", "where to walk: altar once carrying enough gems (or endgame), else cleared groups to capture, else living non-monolith camps")
def goals() -> Tiles:
    gm = gems()
    late = round() > 1850
    if gm >= 30 or (gm > 0 and (late or team_gems() + gm >= 1000)):
        acc = near(tile(-5, -5), 0)
        for a in altars() - locked_altars():
            acc = acc | near(a, 1)
        if size(acc) > 0:
            return acc
    cap = near(tile(-5, -5), 0)
    live = near(tile(-5, -5), 0)
    for g in range(num_groups()):
        if not group_respawning(g):
            gt = group_tiles(g)
            if group_reward(g):
                cap = cap | gt
            else:
                t0 = best(gt, lambda t: 0 - t.x - t.y)
                if valid(t0) and spawn_type(t0) == MONOLITH:
                    continue
                live = live | gt
    if size(cap) > 0:
        return cap
    if size(live) == 0 and gm > 0:
        acc = near(tile(-5, -5), 0)
        for a in altars() - locked_altars():
            acc = acc | near(a, 1)
        return acc
    return live
```

