@gene('s1', 'value of doing this option now; recall follows the retreat state, skipped near home (walking is faster) or with an enemy close enough to cancel it')
def score(o: Option) -> Num:
    if o.kind == PICK:
        return 1
    if o.kind == BUY:
        return 100 if o.item == 6 else 0
    if o.kind == RECALL:
        if not LOW:
            return 0
        p = me().pos
        if at(HF, p) <= 6:
            return 0
        e = nearest(ET, p)
        if valid(e):
            if dist(p, e) <= 3:
                return 0
        return 90
    if o.kind == ATTACK:
        if o.unit.is_champion:
            return 80
        return 60 if gems() == 0 else 0
    if o.kind == CAST:
        return cast_value(o)
    if o.kind == TRIBUTE:
        return 70
    if o.kind == MOVE:
        p = progress(o.tile)
        return 49 + p if p > 0 else 0
    return 0
```

