@gene('Z4a', 'compute the goal field once per turn; retreat home earlier (40%, or 50% when carrying many gems) with hysteresis; home field cached once; cache whether enemy champions / awake camps are close for ability decisions', parents=['s4'])
def update() -> None:
    hf = me().health_frac
    mp = me().pos
    if LOW:
        if hf > 0.9:
            LOW = False
    else:
        lim = 0.4
        if gems() >= 40:
            lim = 0.5
        if hf < lim and not channeling():
            LOW = True
    ECLOSE = any(u.is_champion and dist(u.pos, mp) <= 4 for u in enemies())
    CCLOSE = any(is_awake(c) and dist(c.pos, mp) <= 2 for c in camps())
    if LOW:
        if not HSET:
            HF = field(my_spawn())
            HSET = True
    else:
        GF = goal_field()
