@gene('Z4b', 'value of casting an ability option; finish low enemy champions first, shield in close fights (always when retreating) using per-turn cached threat flags, heal the lowest target, dash toward goals or home, dash onto weak enemies when healthy', parents=['s1'])
def cast_value(o: Option) -> Num:
    k = slot_kind(o.slot)
    if k == AB_DAMAGE or k == AB_AOE or k == AB_CC:
        if exists(o.unit):
            if o.unit.is_champion and o.unit.is_enemy:
                if o.unit.health_frac < 0.4:
                    return 85
                if k == AB_CC and is_tributing(o.unit):
                    return 90
                return 75
            if o.unit.is_camp:
                if gems() == 0:
                    return 55
                if is_awake(o.unit) and dist(o.unit.pos, me().pos) <= 2:
                    return 55
        return 0
    hf = me().health_frac
    if k == AB_SHIELD:
        if ECLOSE and (hf < 0.9 or LOW):
            return 72
        if CCLOSE and (hf < 0.7 or LOW):
            return 72
        return 0
    if k == AB_HEAL:
        if exists(o.unit) and not o.unit.is_enemy:
            return 72 if o.unit.health_frac < 0.6 else 0
        return 72 if hf < 0.6 else 0
    if k == AB_DASH:
        if valid(o.tile):
            p = progress(o.tile)
            if LOW:
                return 50 + p if p >= 2 else 0
            if hf > 0.6 and ECLOSE:
                if any(u.is_champion and u.health_frac < 0.35 and dist(u.pos, o.tile) <= 1 for u in enemies()):
                    return 70
            if hf > 0.5:
                return 42 + p if p >= 2 else 0
        return 0
    return 0
