@gene('s4', 'how much closer a step brings me to the goals, or home when retreating (cached fields); when retreating, avoid stepping into tiles near enemy champions; 0 when either end is unreachable')
def progress(t: Tile) -> Num:
    f = HF if LOW else GF
    a = at(f, me().pos)
    b = at(f, t)
    if a >= 100000000 or b >= 100000000:
        return 0
    d = a - b
    if LOW:
        if t in DANGER:
            d -= 1.5
        elif me().pos in DANGER:
            d += 0.5
    return d
```
